import { readFile } from "fs/promises";
import { join } from "path";
import { Collection } from "../../utils/collection";
import { logger } from "../../utils/logger";
import type { ItemsInfo } from "../../scripts/generate-wiki";

/** Item wiki metadata (descriptions, recipes, play mods) keyed by item id. */
export const itemsWiki: Collection<number, ItemsInfo> = new Collection();

/**
 * Loads `.cache/wiki.json` generated by `bun run wiki`. Entries with an invalid
 * shape are skipped, so a partially broken scrape never breaks the server.
 */
export async function loadItemsWiki(path = join(".cache", "wiki.json")): Promise<void> {
  itemsWiki.clear();
  let raw: string;
  try {
    raw = await readFile(path, "utf8");
  } catch {
    logger.warn({ path }, "wiki metadata not found, item descriptions and play mods are unavailable");
    return;
  }

  try {
    const parsed = JSON.parse(raw) as unknown;
    if (!Array.isArray(parsed)) throw new Error("wiki.json is not an array");

    let skipped = 0;
    for (const entry of parsed as Array<Partial<ItemsInfo>>) {
      if (typeof entry?.id !== "number" || entry.id <= 0 || entry.id > 65535 || typeof entry.name !== "string") {
        skipped++;
        continue;
      }
      itemsWiki.set(entry.id, entry as ItemsInfo);
    }
    logger.info({ count: itemsWiki.size, skipped, path }, "wiki metadata loaded");
  } catch (err) {
    logger.warn({ err, path }, "failed to parse wiki metadata");
  }
}

export function getItemInfo(id: number): ItemsInfo | undefined {
  return itemsWiki.get(id);
}
